-- ══════════════════════════════════════════════════════════════════════════════
-- deploy.sql — DATOS DE PRODUCCIÓN. Solo INSERT; la estructura la pone database.sql.
--
-- Registros REALES del colegio, extraídos del volcado de `bilbaocp_colegiobilbao`
-- del 21-09-2026 (phpMyAdmin 5.2.3 / MariaDB 11.4.13). Los datos van TAL CUAL
-- salieron de producción: no se ha corregido, rellenado ni normalizado ninguna fila.
-- ⚠️ Con UNA excepción, marcada donde está: la contraseña de `alexander.oliva@`
--    (id 2, el administrador) se fija a `Tlalmimilolpan39%` — ver credenciales.md.
--
-- Uso:  mysql -u root -p colegiobilbao < database/database.sql
--       mysql -u root -p colegiobilbao < database/deploy/deploy.sql
--
-- ⚠️ Con --default-character-set=utf8mb4, o el cliente manda en latin1 y los acentos
--    entran doblemente codificados sin dar un solo error.
--
-- ── Adaptado al esquema vigente ───────────────────────────────────────────────
-- El volcado salía de una base que aún no tenía los últimos cambios. Aquí no hacen
-- falta ALTER: cada INSERT lleva su lista de columnas explícita, y lo que el volcado
-- no traía entra por el DEFAULT de database.sql.
--
--   · `activo` (usuarios, aulas, grupos, materias) → DEFAULT 1: todo de alta, que es
--     lo que era antes de que existiera la baja lógica.
--   · `eventos.icono` → NULL = el icono del `tipo`. La tabla va vacía de todas formas.
--   · `usuarios.fecha_nacimiento` → las filas conservan su valor, NULL incluido; el
--     DEFAULT '2000-01-01' solo afecta a las altas futuras.
--   · `ajustes`, `visitas`, `actualizaciones`, `actualizacion_vistas` y
--     `solicitudes_password` no tienen datos en producción: se quedan vacías.
--
-- ⚠️ Estos datos SÍ llevan operación —504 horarios, 116 suplencias, 206 horas de
--    cobertura y 8 intercambios—, al contrario de lo que decía la regla vieja. Lo
--    que sigue vacío es `eventos`, `noticias` y los catálogos nuevos.
-- Ver database/CLAUDE.md antes de tocarlo.
-- ══════════════════════════════════════════════════════════════════════════════
SET NAMES utf8mb4;
-- ⚠️ Los TIMESTAMP del volcado están en UTC (phpMyAdmin exporta con esta misma
-- línea). Sin ella el servidor los interpreta en su zona local y toda fecha de
-- creación se desplaza — 6 horas con la zona de México, y sin un solo error.
SET time_zone = "+00:00";
-- Las tablas se cargan en el orden de database.sql, pero los datos reales tienen
-- referencias cruzadas (una suplencia la creó un usuario que a su vez…), así que las
-- comprobaciones se apagan durante la carga y se reactivan en la última línea.
SET FOREIGN_KEY_CHECKS = 0;

